WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.DEL_YN = 'N'
  /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기 사업장만 */

    AND A.SITE_CD = #{scopeSiteCd}


    AND A.SITE_CD = #{siteCd}


    AND A.STATUS_CD = #{statusCd}


    AND A.MANAGER_USER_CD = #{managerUserCd}


    AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')


    AND DATE(A.INSERT_DATE) >= #{startDate}


    AND DATE(A.INSERT_DATE) <= #{endDate}

