/* Tbm02Mapper.selectSessionListCount */
SELECT COUNT(1)
FROM TB_TBM_SESSION A

/* Tbm02Mapper.selectSessionGuard */
SELECT
	A.SESSION_CD		AS sessionCd
	, A.SITE_CD			AS siteCd
	, A.STATUS_CD		AS statusCd
	, A.MANAGER_USER_CD	AS managerUserCd
FROM TB_TBM_SESSION A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SESSION_CD = #{sessionCd}
  AND A.DEL_YN = 'N'

