/* Tbm02Mapper.cancelSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'CANCELLED'
	, CANCELLED_AT	= NOW()
	, CANCEL_REASON	= #{cancelReason}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD IN ('DRAFT', 'OPENED')

/* Tbm02Mapper.prepareSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD				= 'OPENED'
	, TITLE					= #{title}
	, CONTENT_BODY			= #{contentBody}
	, ENTRY_PWD				= #{entryPwd}
	, MANAGER_GPS_LAT		= #{managerGpsLat}
	, MANAGER_GPS_LON		= #{managerGpsLon}
	, GPS_VERIFY_TYPE_CD	= IFNULL(#{gpsVerifyTypeCd}, GPS_VERIFY_TYPE_CD)
	, GPS_VERIFY_RADIUS_M	= IFNULL(#{gpsVerifyRadiusM}, GPS_VERIFY_RADIUS_M)
	, GPS_MANUAL_CONFIRM_YN	= #{gpsManualConfirmYn}
	, OPENED_AT				= IFNULL(OPENED_AT, NOW())
	, PREP_START_AT			= NOW()
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'DRAFT'

/* Tbm02Mapper.updateEntryPwd */
UPDATE TB_TBM_SESSION
SET
	ENTRY_PWD		= #{pwd}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'OPENED'

/* Tbm02Mapper.updateExitPwd */
UPDATE TB_TBM_SESSION
SET
	EXIT_PWD		= #{pwd}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'COMPLETED'

/* Tbm02Mapper.startSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'IN_PROGRESS'
	, STARTED_AT	= NOW()
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'OPENED'

/* Tbm02Mapper.extendPrep */
UPDATE TB_TBM_SESSION
SET
	PREP_START_AT	= NOW()
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'OPENED'
  AND PREP_START_AT IS NOT NULL
  AND PREP_START_AT > (NOW() - INTERVAL 15 MINUTE)

/* Tbm02Mapper.completeSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'COMPLETED'
	, ENDED_AT		= NOW()
	, EXIT_PWD		= #{exitPwd}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'IN_PROGRESS'

mapper.select:
/* Tbm02Mapper.selectContentOptions */ SELECT A.MTRL_CD AS mtrlCd , A.TITLE AS title , A.MTRL_TYPE AS mtrlType , BD.BAIM_VAL_D_NM AS mtrlTypeNm , A.SITE_CD AS siteCd , CASE WHEN A.SITE_CD IS NULL THEN 'Y' ELSE 'N' END AS isCommonContent , ( SELECT COUNT(I.MTRL_ITEM_CD) FROM TB_TBM_EDU_MTRL_ITEM I WHERE I.MTRL_CD = A.MTRL_CD AND I.USE_YN = 'Y' ) AS itemCnt FROM TB_TBM_EDU_MTRL A LEFT OUTER JOIN TB_BAIM_VAL_D BD ON ( BD.CMPNY_CD = A.CMPNY_CD AND BD.BAIM_VAL_CD = 'COM003' AND BD.BAIM_VAL_D_CD = A.MTRL_TYPE AND BD.USE_YN = 'Y' ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.USE_YN = 'Y' /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기사업장+회사공통 */
AND (A.SITE_CD IS NULL OR A.SITE_CD = #{scopeSiteCd})
AND A.SITE_CD IS NULL
/* 세션 콘텐츠 선택: 해당 사업장 자료 + 회사공통(SITE_CD IS NULL) 자료 포함 */ AND (A.SITE_CD IS NULL OR A.SITE_CD = #{siteCd})
AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.SITE_CD IS NOT NULL, A.TITLE

/* Tbm02Mapper.selectRiskOptions */ SELECT A.SITE_CD AS siteCd , A.PROCESS_CD AS processCd , C.BAIM_VAL_D_NM AS processNm , A.RISK_TYPE_CD AS riskTypeCd , D.RISK_TYPE_NM AS riskTypeNm , A.HAZARD_CD AS hazardCd , CASE WHEN A.HAZARD_CD = 'self' THEN A.ASSESSMENT_DESC ELSE E.HAZARD_NM END AS hazardNm , A.ASSESSMENT_CD AS assessmentCd , A.ASSESSMENT_STATUS AS assessmentStatus , B.SYST_VAL_D_NM AS assessmentStatusNm FROM TB_RISK_ASSESSMENT A LEFT OUTER JOIN ( SELECT G.SYST_VAL_D_CD, G.SYST_VAL_D_NM FROM TB_SYST_VAL_D G WHERE G.SYST_VAL_CD = 'SYS011' AND G.USE_YN = 'Y' ) B ON ( A.ASSESSMENT_STATUS = B.SYST_VAL_D_CD ) LEFT OUTER JOIN TB_BAIM_VAL_D C ON ( C.CMPNY_CD = A.CMPNY_CD AND C.BAIM_VAL_CD = 'COM002' AND C.BAIM_VAL_D_CD = A.PROCESS_CD AND C.USE_YN = 'Y' ) LEFT OUTER JOIN TB_RISK_TYPE D ON ( A.CMPNY_CD = D.CMPNY_CD AND A.RISK_TYPE_CD = D.RISK_TYPE_CD ) LEFT OUTER JOIN TB_RISK_SITE_HAZARD E ON ( A.CMPNY_CD = E.CMPNY_CD AND A.RISK_TYPE_CD = E.RISK_TYPE_CD AND A.HAZARD_CD = E.HAZARD_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} /* 스코프 필터: master/safe는 회사 전체, 그 외는 자기 사업장만 */
AND A.SITE_CD = #{scopeSiteCd}
AND A.SITE_CD = #{siteCd}
AND A.PROCESS_CD = #{processCd}
ORDER BY A.SITE_CD, A.PROCESS_CD, A.RISK_TYPE_CD, A.HAZARD_CD

/* Tbm02Mapper.selectRegularCandidates */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , NULL AS mblNoLast4 , CASE WHEN EXISTS ( SELECT 1 FROM TB_TBM_ATTENDANCE AT WHERE AT.CMPNY_CD = #{gvCmpnyCd} AND AT.SESSION_CD = #{sessionCd} AND AT.USER_TYPE_CD = 'REGULAR' AND AT.USER_CD = U.USER_CD AND AT.DEL_YN = 'N' ) THEN 1 ELSE 0 END AS alreadyEntered FROM TB_USER U LEFT OUTER JOIN TB_SITE ST ON ( U.CMPNY_CD = ST.CMPNY_CD AND U.SITE_CD = ST.SITE_CD ) WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.ACCOUNT_STATUS = '01'
AND ( U.USER_NM LIKE CONCAT('%', #{keyword}, '%') OR U.USER_ID LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY U.USER_NM, U.USER_CD LIMIT 100

/* Tbm02Mapper.selectDailyCandidates */ SELECT DU.USER_CD AS userCd , DU.USER_ID AS userId , DU.USER_NM AS userNm , DU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , DU.MBL_NO_LAST4 AS mblNoLast4 , CASE WHEN EXISTS ( SELECT 1 FROM TB_TBM_ATTENDANCE AT WHERE AT.CMPNY_CD = #{gvCmpnyCd} AND AT.SESSION_CD = #{sessionCd} AND AT.USER_TYPE_CD = 'DAILY' AND AT.USER_CD = DU.USER_CD AND AT.DEL_YN = 'N' ) THEN 1 ELSE 0 END AS alreadyEntered FROM TB_DAILY_USER DU LEFT OUTER JOIN TB_SITE ST ON ( DU.CMPNY_CD = ST.CMPNY_CD AND DU.SITE_CD = ST.SITE_CD ) WHERE DU.CMPNY_CD = #{gvCmpnyCd} AND DU.SITE_CD = #{siteCd} AND DU.USE_YN = 'Y' AND DU.ACCOUNT_STATUS = '01' AND DU.WITHDRAWAL_DATE IS NULL AND DU.WORK_EXPIRE_DATE >= DATE_FORMAT(NOW(), '%Y%m%d')
AND ( DU.USER_NM LIKE CONCAT('%', #{keyword}, '%') OR DU.USER_ID LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY DU.USER_NM, DU.USER_CD LIMIT 100

/* Tbm02Mapper.countEntryTarget */


		SELECT COUNT(1)
		FROM TB_DAILY_USER DU
		WHERE DU.CMPNY_CD = #{gvCmpnyCd}
		  AND DU.SITE_CD = #{siteCd}
		  AND DU.USER_CD = #{userCd}
		  AND DU.USE_YN = 'Y'
		  AND DU.ACCOUNT_STATUS = '01'
		  AND DU.WITHDRAWAL_DATE IS NULL
		  AND DU.WORK_EXPIRE_DATE >= DATE_FORMAT(NOW(), '%Y%m%d')


		SELECT COUNT(1)
		FROM TB_USER U
		WHERE U.CMPNY_CD = #{gvCmpnyCd}
		  AND U.SITE_CD = #{siteCd}
		  AND U.USER_CD = #{userCd}
		  AND U.USE_YN = 'Y'
		  AND U.ACCOUNT_STATUS = '01'

/* Tbm02Mapper.selectAttendanceSlot */
SELECT
	AT.ATTENDANCE_CD	AS attendanceCd
	, AT.DEL_YN			AS delYn
FROM TB_TBM_ATTENDANCE AT
WHERE AT.CMPNY_CD = #{gvCmpnyCd}
  AND AT.SESSION_CD = #{sessionCd}
  AND AT.USER_TYPE_CD = #{userTypeCd}
  AND AT.USER_CD = #{userCd}
LIMIT 1

