/* Tbm02Mapper.insertManagerEntry */
INSERT INTO TB_TBM_ATTENDANCE (
	  ATTENDANCE_CD
	, CMPNY_CD
	, SESSION_CD
	, USER_TYPE_CD
	, USER_CD
	, ENTRY_TYPE_CD
	, ENTRY_BY_MANAGER_USER_CD
	, ENTRY_AT
	, DEL_YN
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
)
VALUES (
	  CONCAT('A', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'TBM_ATTENDANCE_CD'))
	, #{gvCmpnyCd}
	, #{sessionCd}
	, #{userTypeCd}
	, #{userCd}
	, 'MANAGER_DIRECT'
	, #{managerUserCd}
	, NOW()
	, 'N'
	, #{managerUserCd}
	, NOW()
	, #{managerUserCd}
	, NOW()
)

