/* Tbm02Mapper.ejectAttendance */
UPDATE TB_TBM_ATTENDANCE
SET
	  DEL_YN				= 'Y'
	, EXIT_FORCED_REASON	= #{reason}
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND ATTENDANCE_CD = #{attendanceCd}
  AND DEL_YN = 'N'
